// ── Países que faltaban y nombres que difieren entre mapas (15/08/2026) ───────
//
// BÉLGICA NO ESTABA en el mapa de DHL ni en el de UPS exportación (solo en UPS impo).
// Lo encontró la oficina el 15/08 cotizando una impo desde Bélgica: UPS cotizaba y DHL
// decía que el país no existía — y una EXPO a Bélgica no cotizaba por ninguno. Va en
// zona 4 en los dos, igual que todos sus vecinos (Países Bajos, Luxemburgo, Francia,
// Alemania) y que el "Europa Occidental" del tarifario papel de DHL.
//
// Los demás son EL MISMO PAÍS escrito distinto en cada mapa (DHL dice "Antigua", UPS
// "Antigua y Barbuda"). Cada mapa recibe el nombre que usa el otro, con SU zona, para que
// el país resuelva en los dos couriers sin importar de qué lista salió el nombre.
Object.assign(ZONAS_DHL,{
  'Bélgica':4,
  'Antigua y Barbuda':2,             // DHL lo llama "Antigua" (zona 2)
  'San Vicente y Las Granadinas':2,  // DHL: "San Vicente"
  'St. Kitts y Nevis':2,             // DHL: "St. Kitts"
  'Macedonia':4,                     // DHL: "Macedonia del Norte"
  'Guyana Francesa':2,               // DHL: "Guayana Francesa"
});
Object.assign(ZONAS_UPS,{
  'Bélgica':4,
  'Antigua':3,                       // UPS: "Antigua y Barbuda"
  'San Vicente':3,
  'St. Kitts':3,
  'Macedonia del Norte':6,           // UPS: "Macedonia"
  'Guayana Francesa':3,              // UPS: "Guyana Francesa"
  // 20/08/2026: faltaba la grafía CON Y, que es la que usa el mapa de DHL y por lo tanto
  // la que aparece en los desplegables. Sin esto, cotizar la Guayana Francesa por UPS
  // exportación fallaba con "ese país no existe" — el mismo síntoma que tuvo Bélgica.
  // Las dos grafías apuntan a la misma zona a propósito.
  'Guyana Francesa':3,
});
Object.assign(ZONAS_UPS_I,{
  'Antigua':2,
  'San Vicente':2,
  'St. Kitts':2,
  'Guayana Francesa':2,
});

// ── Resolución de zona por courier y tipo ────────────────────────────────────
function resolverZona(pais, courier, tipo) {
  if (courier === 'DHL') return ZONAS_DHL[pais] || null;
  return (tipo === 'import' ? ZONAS_UPS_I : ZONAS_UPS)[pais] || null;
}

