// ── Funciones de lookup ───────────────────────────────────────────────────────

function getPesoVol(l,a,al){return Math.ceil((l*a*al)/5000*2)/2;}

function getDHL(tabla,zona,pf){
  const c=zona-1;
  if(pf<=10){
    const p=Math.ceil(pf*2)/2;
    const r=tabla.find(x=>x[0]===p);
    if(r)return r[c+1];
    const lo=tabla.filter(x=>x[0]<p).pop(),hi=tabla.find(x=>x[0]>p);
    if(lo&&hi){const t=(p-lo[0])/(hi[0]-lo[0]);return lo[c+1]+(hi[c+1]-lo[c+1])*t;}
    return(lo||hi)[c+1];
  }
  // Arriba de 10 kg se LEE la tabla oficial en vez de calcularla. La fórmula incremental
  // que había acá no reproducía el tarifario: arriba de 70 kg la exportación se iba
  // 10 USD para arriba en cada envío, porque aplicaba la tarifa del tramo alto a todo el
  // excedente sobre 30 kg en lugar de acumular tramo por tramo. Entre 10 y 70 kg erraba
  // por centavos.
  //
  // Los documentos no tienen tabla arriba de 2 kg. Acá no se llega nunca con una tabla de
  // documentos (el motor solo la usa hasta 2 kg), pero se devuelve la última fila en vez
  // de romper con un error de índice.
  if(tabla===DHL_E_DOC||tabla===DHL_I_DOC)return tabla[tabla.length-1][c+1];
  const esImport=tabla===DHL_I_PKG;
  const grande=esImport?DHL_I_PKG_MED:DHL_E_PKG_BIG;
  // El tarifario va de a medio kilo y después de a un kilo; DHL redondea para arriba, así
  // que se toma la primera fila que alcance el peso.
  const fila=grande.find(x=>x[0]>=pf);
  if(fila)return fila[c+1];
  const ultima=grande[grande.length-1];
  // Arriba de la última fila (300 kg en exportación) se extrapola con el valor por kilo
  // del PDF. En importación no se llega: de 50 kg en adelante manda la tabla DHL_I_BIG.
  if(esImport)return ultima[c+1];
  return ultima[c+1]+Math.ceil(pf-ultima[0])*DHL_E_PK_300[c];
}

function getDHLBig(zona,pf){
  const c=zona-1;
  const pfCeil=Math.ceil(pf);
  const r=DHL_I_BIG.find(x=>x[0]===pfCeil);
  if(r)return r[c+1];
  const lo=DHL_I_BIG.filter(x=>x[0]<pfCeil).pop();
  const hi=DHL_I_BIG.find(x=>x[0]>pfCeil);
  if(lo&&hi){const t=(pfCeil-lo[0])/(hi[0]-lo[0]);return lo[c+1]+(hi[c+1]-lo[c+1])*t;}
  if(pf>300)return DHL_I_BIG[DHL_I_BIG.length-1][c+1]+(pf-300)*DHL_I_BIG_PK[c];
  return(lo||hi)[c+1];
}

function getUPS(liqd,pk,mn,zona,pf){
  const c=zona-1;
  const p=Math.ceil(pf*2)/2;
  if(p<=31.5){
    const r=liqd.find(x=>x[0]===p);
    if(r)return r[c+1];
    const lo=liqd.filter(x=>x[0]<p).pop(),hi=liqd.find(x=>x[0]>p);
    if(lo&&hi){const t=(p-lo[0])/(hi[0]-lo[0]);return lo[c+1]+(hi[c+1]-lo[c+1])*t;}
    return(lo||hi)[c+1];
  }
  return Math.max(mn[c],Math.ceil(pf)*pk[c]);
}

function getUPSSaverEsIt(pais,pf){
  const p=Math.ceil(pf*2)/2;
  const col=pais==='España'?1:2;
  const pk=pais==='España'?UPS_SAVER_ES_PK:UPS_SAVER_IT_PK;
  if(p<=31.5){
    const r=UPS_SAVER_ES_IT.find(x=>x[0]===p);
    if(r)return r[col];
    const lo=UPS_SAVER_ES_IT.filter(x=>x[0]<p).pop(),hi=UPS_SAVER_ES_IT.find(x=>x[0]>p);
    if(lo&&hi){const t=(p-lo[0])/(hi[0]-lo[0]);return lo[col]+(hi[col]-lo[col])*t;}
    return(lo||hi)[col];
  }
  return UPS_SAVER_ES_IT[UPS_SAVER_ES_IT.length-1][col]+(p-31.5)*pk;
}

// ── Pricing functions ─────────────────────────────────────────────────────────

// Surge fee UPS (por kg de peso facturable). Las tablas de exportación e importación son
// DISTINTAS, por eso hay que mirar el sentido del envío:
//   Exportación: ISMEA 2.95 · Israel y E.A.U. 3.30 · EE.UU. y resto del mundo 0.50
//   Importación: ISMEA 2.95 · E.A.U. 3.30 · India 1.45 · China/HK/Macao 0.70 · resto 0.50
// UPS eliminó el recargo de las importaciones DESDE ISRAEL el 24-may-2026; antes acá se
// cobraba 3.30 en los dos sentidos.
function getSurge(pais,tipo,pf){
  if(pais==='Emiratos Árabes Unidos')return pf*3.30;
  if(tipo==='export'&&pais==='Israel')return pf*3.30;
  if(ISMEA.has(pais))return pf*2.95;
  if(tipo==='import'&&INDIA.has(pais))return pf*1.45;
  if(tipo==='import'&&CHINA_HK_MACAO.has(pais))return pf*0.70;
  return pf*0.50;
}

// Seguro propio del cliente (clientes.seguro_pct_propio / seguro_min_propio).
// Hay clientes con un porcentaje negociado distinto del 1,5% de lista —1% en Gianastasio
// y Cueros—, y el piso tampoco es igual para todos, así que van los dos por cliente.
//
// Cuando el cliente tiene uno cargado, REEMPLAZA la escala del courier entera, en DHL y en
// UPS por igual: no quedan ni el escalón de USD 15 de UPS ni el mínimo de 17,50 de DHL.
// Es a propósito: si el cliente negoció "1% con mínimo 10", eso es lo que paga, y dejar el
// escalón viejo abajo lo haría pagar 15 en un envío de USD 200 que debería costarle 10.
//
// El valor 0 sigue sin pagar seguro en los dos casos: no hay nada que asegurar.
// @param {{pct:number, min:number|null}|null} propio
// Ojo con el null: isFinite(null) devuelve TRUE (null se convierte en 0). Un cliente con
// el porcentaje vacío y un mínimo cargado terminaba cobrando ese mínimo en vez de volver a
// la escala del courier, que es lo que corresponde. Hay que descartarlo a mano.
const _numOnull=(x)=>(x===null||x===undefined||x===''||!isFinite(Number(x)))?null:Number(x);

function seguroPropioMonto(v,propio){
  if(!propio)return null;
  const pct=_numOnull(propio.pct);
  if(pct===null)return null;
  if(v<=0)return{monto:0,desc:'Sin seguro (valor = 0)'};
  const raw=parseFloat((v*(pct/100)).toFixed(2));
  const piso=_numOnull(propio.min)===null?0:Number(propio.min);
  const m=parseFloat(Math.max(piso,raw).toFixed(2));
  const pctTxt=`${pct}%`;
  if(raw<piso)return{monto:m,desc:`Seguro del cliente: mínimo USD ${piso.toFixed(2)} (${pctTxt} daba USD ${raw.toFixed(2)})`};
  return{monto:m,desc:`Seguro del cliente: ${pctTxt} × USD ${v.toLocaleString('es-AR')} = USD ${m.toFixed(2)}`};
}

function calcSeguroUPS(v,propio){
  const p=seguroPropioMonto(v,propio); if(p)return p;
  if(v<=0)return{monto:0,desc:'Sin seguro (valor = 0)'};
  if(v<100)return{monto:0,desc:'Sin cargo (valor menor a USD 100)'};
  if(v<=1000)return{monto:15,desc:'Seguro: USD 15.00 fijo (USD 100–1.000)'};
  const m=parseFloat((v*0.015).toFixed(2));
  return{monto:m,desc:`Seguro: 1.5% × USD ${v.toLocaleString('es-AR')} = USD ${m.toFixed(2)}`};
}

// Protección de Documentos de DHL — USD 7,50 por envío. Precio de tarifario, no de Nova:
// si DHL lo actualiza, se cambia acá y queda cambiado en el cotizador, en el alta de envío,
// en Salidas y en la liquidación.
const DHL_PROTECCION_DOC=7.50;

function calcSeguroDHL(v,propio){
  const p=seguroPropioMonto(v,propio); if(p)return p;
  if(v<=0)return{monto:0,desc:'Sin seguro (valor = 0)'};
  const raw=parseFloat((v*0.015).toFixed(2));
  const m=Math.max(17.50,raw);
  if(raw<17.50)return{monto:17.50,desc:'Seguro DHL: mínimo USD 17.50'};
  return{monto:m,desc:`Seguro DHL: 1.5% × USD ${v.toLocaleString('es-AR')} = USD ${m.toFixed(2)}`};
}

// Extracargos DHL por bulto: sobrepeso (>70 kg real o facturable) y exceso de tamaño
// b.pf puede ser provisto por el caller; si no está, se usa solo b.pr
function calcDHLExtras(bultosProc){
  let sobrepesoTotal=0;
  let excesoTotal=0;
  let noConvencionalTotal=0;
  bultosProc.forEach(b=>{
    const tieneSobrepeso=b.pr>70||(b.pf!==undefined&&b.pf>70);
    if(tieneSobrepeso){
      sobrepesoTotal+=125;
    } else if(b.dims[0]>100||b.dims[1]>80){
      excesoTotal+=23;
    } else if(b.pr>=25&&b.pr<=70){
      // "Pieza no convencional" (non-conveyable): DHL cobra 23 USD por CADA pieza con peso
      // real entre 25 y 70 kg. El tarifario aclara que no acumula con sobrepeso ni con
      // exceso de tamaño — de ahí la cadena de else if. El sistema no lo cobraba.
      noConvencionalTotal+=23;
    }
  });
  return{sobrepesoTotal,excesoTotal,noConvencionalTotal};
}

// Extracargos UPS por bulto: manejo adicional (27.65) y Paquete de Mayor Tamaño (120.10).
//
// Cuatro reglas del tarifario 2026 que antes no estaban:
//  1. El manejo adicional NO se cobra en un bulto que ya paga Paquete de Mayor Tamaño.
//  2. Paquete de Mayor Tamaño tiene una tarifa MÍNIMA a facturar de 40 kg por bulto. Sin
//     esto, una caja voluminosa y liviana se cotizaba por su peso real y UPS la facturaba
//     por 40 kg.
//  3. El manejo por lado largo dispara a partir de 122 cm, no de 120.
//  4. (31/08, OK de Felipe) En un envío de VARIOS paquetes cuyo peso promedio real por
//     paquete excede los 32 kg, el manejo se cobra en CADA paquete — también en los que
//     solos no llegan a 25 kg. Texto de la guía: "Cada paquete, dentro de un envío de
//     múltiples paquetes, donde el peso promedio por paquete exceda los 32 Kg." Lo
//     destapó la hoja de extracargos de la oficina (17/04/26): 60 kg + 10 kg = promedio
//     35 → UPS factura DOS manejos y el sistema estimaba uno.
//
// `minPesoExtra` son los kilos que hay que SUMAR al peso facturable del envío para llegar
// al mínimo de 40 kg de cada bulto de mayor tamaño.
function calcUPSDimExtras(bultosProc){
  let manejoCount=0;
  let contornoExtra=0;
  let contornoWarn=false;
  let minPesoExtra=0;
  let minPesoAplicado=false;
  // Regla 4: el promedio se calcula sobre el peso REAL (igual que el criterio de los
  // 25 kg por pieza) y solo existe con más de un paquete.
  const pesoRealTotal=bultosProc.reduce((s,b)=>s+(Number(b.pr)||0),0);
  const promedioAlto=bultosProc.length>1&&(pesoRealTotal/bultosProc.length)>32;
  bultosProc.forEach(b=>{
    const d=b.dims; // [mayor, segundo, menor]
    const contorno=d[0]+2*d[1]+2*d[2];
    let esMayorTamano=false;
    if(contorno>400){contornoWarn=true;}
    else if(contorno>300){contornoExtra+=120.10;esMayorTamano=true;}
    const needsManejo=b.pr>25||d[0]>122||d[1]>76||promedioAlto;
    if(needsManejo&&!esMayorTamano)manejoCount++;
    if(esMayorTamano){
      // Peso facturable del bulto: lo trae el cotizador; el backend manda solo dims y peso
      // real, así que se recalcula el volumétrico con la misma fórmula (l×a×h/5000).
      const pfBulto=(b.pf!==undefined&&b.pf!==null)
        ? Number(b.pf)
        : Math.max(Number(b.pr)||0,(d[0]*d[1]*d[2])/5000);
      if(pfBulto<40){minPesoExtra+=40-pfBulto;minPesoAplicado=true;}
    }
  });
  contornoExtra=parseFloat(contornoExtra.toFixed(2));
  minPesoExtra=parseFloat(minPesoExtra.toFixed(3));
  return{manejoCount,contornoExtra,contornoWarn,minPesoExtra,minPesoAplicado};
}

// ── Topes de aceptación por pieza (deuda 29) ─────────────────────────────────
// AVISOS, NO BLOQUEOS. No mueven ni un centavo del precio: el motor cotiza igual. Lo
// único que hacen es decirle a la oficina, ANTES de pasar el precio, que esa pieza el
// courier no la despacha como está. Nació del caso "alfombras a Australia" (27/08): una
// alfombra de 2,80 m pasaba el cotizador entera y UPS no la toma.
//
//   UPS — lado más largo 274 cm · contorno (largo + 2×ancho + 2×alto) 400 cm · 70 kg
//         reales por pieza. Los tres son topes de aceptación: arriba de ahí no viaja.
//   DHL — pieza estándar de 120 × 80 × 80 cm. Ojo: el PESO no es tope en DHL — arriba
//         de 70 kg la toma y cobra el sobrepeso de 125 USD, que el motor ya cobra.
const TOPES_PIEZA={
  UPS:{lado:274,contorno:400,peso:70},
  DHL:{lado:120,segundo:80},
};

const MSG_CONTORNO_UPS='⚠ Uno o más bultos superan el contorno máximo de 400 cm y no pueden enviarse por UPS.';

// Devuelve { ups:[textos], dhl:[textos] }. Se agrupa por regla, no por bulto: con 22
// cajas iguales fuera de tope, un renglón que dice "22 bultos", no 22 renglones.
function calcTopesPieza(bultosProc){
  let upsLado=0,upsContorno=0,upsPeso=0,dhlPieza=0;
  let maxLado=0,maxContorno=0,maxPeso=0;
  (bultosProc||[]).forEach(b=>{
    const d=b.dims||[0,0,0];
    const contorno=d[0]+2*d[1]+2*d[2];
    const pr=Number(b.pr)||0;
    if(d[0]>TOPES_PIEZA.UPS.lado){upsLado++;maxLado=Math.max(maxLado,d[0]);}
    if(contorno>TOPES_PIEZA.UPS.contorno){upsContorno++;maxContorno=Math.max(maxContorno,contorno);}
    if(pr>TOPES_PIEZA.UPS.peso){upsPeso++;maxPeso=Math.max(maxPeso,pr);}
    // d[2] <= d[1], así que con mirar los dos primeros alcanza.
    if(d[0]>TOPES_PIEZA.DHL.lado||d[1]>TOPES_PIEZA.DHL.segundo)dhlPieza++;
  });
  const plural=(n)=>n===1?'bulto':'bultos';
  const ups=[],dhl=[];
  if(upsLado>0)    ups.push(`⛔ ${upsLado} ${plural(upsLado)} con el lado más largo de más de 274 cm (el mayor mide ${maxLado} cm): UPS no acepta piezas así.`);
  if(upsContorno>0)ups.push(MSG_CONTORNO_UPS);
  if(upsPeso>0)    ups.push(`⛔ ${upsPeso} ${plural(upsPeso)} de más de 70 kg reales (el mayor pesa ${maxPeso} kg): UPS no acepta piezas de más de 70 kg.`);
  if(dhlPieza>0)   dhl.push(`⚠ ${dhlPieza} ${plural(dhlPieza)} ${dhlPieza===1?'supera':'superan'} la pieza estándar de DHL (120 × 80 × 80 cm): confirmar con DHL antes de cerrar el precio.`);
  return{ups,dhl};
}

// Traduce lo que mande el caller a 'normal' | 'extendida' | 'remota'.
// Compatibilidad: quien siga mandando solo `remota:true` (código viejo, envíos ya cargados)
// obtiene 'extendida', que es exactamente la tarifa que el sistema venía cobrando.
function normalizarEntrega(entrega,remota){
  const v=String(entrega??'').trim().toLowerCase();
  if(v==='extendida'||v==='remota'||v==='normal')return v;
  return remota?'extendida':'normal';
}

// Recargo de zona de entrega, por courier.
//   DHL  — un solo cargo: 40.00 USD o 0.80 USD/kg, el mayor
//   UPS  — extendida: 42.15 o 0.92/kg, el mayor
//          remota:    5.86 por envío a Estados Unidos (incluye Alaska y Hawaii);
//                     al resto del mundo, la misma de extendida
function calcZonaEntrega(courier,zonaEntrega,pf,pais){
  if(zonaEntrega!=='extendida'&&zonaEntrega!=='remota')return null;
  if(courier==='DHL'){
    return{label:zonaEntrega==='remota'?'Área remota':'Área extendida',
           monto:Math.max(40,pf*0.8)};
  }
  if(zonaEntrega==='remota'&&pais==='Estados Unidos'){
    return{label:'Área remota (EE.UU.)',monto:5.86};
  }
  return{label:zonaEntrega==='remota'?'Área remota':'Área extendida',
         monto:Math.max(42.15,pf*0.92)};
}

// Impuestos de importación — CALIBRADO CONTRA CUATRO LIQUIDACIONES REALES (28/08/2026):
// dos Notas de Venta de DHL (0280-01693029 y 0280-01692751, ambas China, arancel 20%) y
// dos Facturas-Liquidación de UPS (0013-00991465 China 20% y 0013-00996104 Chequia 16%).
// Lo que las cuatro coinciden en decir, contra lo que esta función suponía antes:
//   · el SEGURO ADUANERO es 1% de (FOB + flete) — no 1,5% del FOB. Clavado en las 4.
//   · derechos = arancel × CIF (el arancel DEPENDE de la mercadería: se vieron 16% y 20%).
//   · tasa de estadística = 3% × CIF (con tope legal de USD 500 por operación).
//   · IVA aduana = 21% × (CIF + derechos + tasa). Exacto en las 4.
//   · el gasto documental es DISTINTO por courier:
//       UPS: "GASTO DOCUMENTAL" FIJO USD 126 (171.108 $ / TC 1358 y 175.707 $ / TC 1394,5
//            dan 126,00 exactos) + IVA 21% sobre él.
//       DHL: "Procesamiento de aranceles e impuestos" = 1,465% × CIF (47,11/3.216,19 y
//            21,72/1.482,93 dan el mismo 1,4648%) + IVA 21% (viene gravado).
//   · DHL además PERCIBE IIBB: 7% (Bs.As. 4% + CABA 3%) sobre el subtotal de servicios
//     (derechos + estadística + procesamiento). En las UPS de muestra vino en 0.
// El resultado sigue siendo un ESTIMADO para el panel del cotizador (no toca costos).
function calcImpuestos(fob,flete,arancel,courier){
  const esDHL=String(courier||'').toUpperCase().includes('DHL');
  const seguroCIF=(fob+flete)*0.01;
  const CIF=fob+flete+seguroCIF;
  const derechos=CIF*arancel;
  // 3% liso: la tasa tiene topes legales por escala, pero en el régimen courier el CIF
  // no llega a donde muerden, y las 4 liquidaciones muestran el 3% sin tope.
  const tasaEst=CIF*0.03;
  const conceptos=CIF+derechos+tasaEst;
  const ivaAduana=conceptos*0.21;
  const gastoDoc=esDHL?CIF*0.014648:126;
  const ivaGastoDoc=gastoDoc*0.21;
  const percIIBB=esDHL?(derechos+tasaEst+gastoDoc)*0.07:0;
  const total=derechos+tasaEst+ivaAduana+gastoDoc+ivaGastoDoc+percIIBB;
  return{CIF,seguroCIF,derechos,tasaEst,ivaAduana,gastoDoc,ivaGastoDoc,percIIBB,total};
}

// ── Orquestación canónica por servicio ───────────────────────────────────────
// Fuente única de verdad: replica el orden exacto de cotizar() del v8.
// params.bultosProc: [{ dims:[mayor,seg,menor], pr }] (ya procesados, dims ordenadas)
// params.pf: peso facturable total ya calculado
// Retorna null si el país no se encuentra y no hay zonaOverride.
function cotizarServicio(servicio, params) {
  const {
    pais='', tipo='export',
    pf=0, fob=0,
    fuelPct=0, profitPct=0,
    bultosProc=[],
    residencial=false, remota=false,
    // Zona de entrega: 'normal' | 'extendida' | 'remota'. Son DOS cargos distintos del
    // tarifario de UPS y el sistema tenía un solo casillero:
    //   Área extendida → 42.15 o 0.92/kg, el mayor
    //   Área remota    → 5.86 por envío a EE.UU., y 42.15 / 0.92 al resto
    // DHL tiene un solo cargo de zona (40 o 0.80/kg), así que ahí las dos dan lo mismo.
    // `remota:true` sin `entrega` se lee como 'extendida', que es la tarifa que el sistema
    // venía cobrando: así ningún envío ya cargado cambia de precio.
    entrega,
    contenido='paquete',
    zonaOverride,
    ddp=false,
    // Protección de Documentos de DHL: USD 7,50 por envío, a pedido del cliente.
    // Tarifario DHL Express Argentina, hoja "Servicios y cargos públicos": es un servicio
    // OPCIONAL ("si va a enviar documentos valiosos, pasaportes, solicitudes para visas o
    // certificados legales"), por eso es una tilde y no algo automático. Solo DHL.
    proteccionDoc=false,
    // Precio de venta del flete en USD POR KILO. Es para los clientes que no trabajan con
    // un % de ganancia sino con una tarifa fija por kilo (ver clientes.modo_tarifa y
    // tarifa_kg_overrides). Cuando viene, REEMPLAZA al flete con margen: el flete de venta
    // pasa a ser precioKgVenta × peso facturable y profitPct se ignora.
    // No toca nada más: fuel, seguro, surge, DDP y zona de entrega siguen igual.
    precioKgVenta=null,
    // Seguro negociado del cliente: { pct, min } o null. Cuando viene, reemplaza la escala
    // de seguro del courier en DHL y en UPS. Ver seguroPropioMonto().
    seguroPropio=null,
  } = params;
  const fuel   = fuelPct   / 100;
  const profit = profitPct / 100;
  const zonaEntrega = normalizarEntrega(entrega, remota);
  const kgVenta = Number(precioKgVenta);
  const usaPorKg = Number.isFinite(kgVenta) && kgVenta > 0;

  // ── DHL ──────────────────────────────────────────────────────────────────────
  if(servicio==='DHL'){
    const zona=resolverZona(pais,'DHL',tipo)||(zonaOverride?Number(zonaOverride):null);
    if(!zona)return null;
    const esDoc=contenido==='documento'&&pf<=2;
    let fleteBase;
    // tarifa50: el envío se despacha por la cuenta "MAS 50 KGS", que es OTRA cuenta de DHL.
    // Viaja hasta la pantalla para que la oficina sepa contra qué cuenta emitir la guía.
    let tarifa50=false;
    if(tipo==='import'&&!esDoc&&pf>50){
      fleteBase=getDHLBig(zona,pf);
    } else {
      const tabla=esDoc?(tipo==='export'?DHL_E_DOC:DHL_I_DOC):(tipo==='export'?DHL_E_PKG:DHL_I_PKG);
      fleteBase=getDHL(tabla,zona,pf);
      // Exportación arriba de 50 kg: hay DOS tarifas y se elige la más barata.
      // Se comparan COSTOS COMPLETOS, no fletes pelados: la de siempre paga GoGreen y la
      // +50 no, y el GoGreen (0,98/kg) pesa más que la diferencia de flete. Criterio de
      // Felipe (01/09): "siempre hacemos lo más barato". Con las tarifas de hoy la +50 gana
      // en las SEIS zonas en todo el rango 51–300 kg; la comparación queda igual escrita
      // para que la regla siga siendo cierta el día que cambie alguna de las dos tablas.
      if(tipo==='export'&&!esDoc&&pf>50){
        const flete50=getDHLE50(zona,pf);
        if(flete50){
          const costoNormal=fleteBase*(1+fuel)+parseFloat((pf*0.98).toFixed(2));
          const costo50    =flete50*(1+fuel);
          if(costo50<costoNormal){fleteBase=flete50;tarifa50=true;}
        }
      }
    }
    if(!fleteBase)return null;
    const aplicaGoGreen=!tarifa50&&!(tipo==='import'&&pf>50);
    const goGreen=aplicaGoGreen?parseFloat((pf*0.98).toFixed(2)):0;
    const{sobrepesoTotal,excesoTotal,noConvencionalTotal}=calcDHLExtras(bultosProc);
    const topesDHL=calcTopesPieza(bultosProc).dhl;
    const seguroObj=calcSeguroDHL(fob,seguroPropio);
    const extras=[];
    if(goGreen>0)           extras.push([`GoGreen (${Number(pf.toFixed(3))} kg × USD 0.98)`,goGreen]);
    if(sobrepesoTotal>0)    extras.push(['Sobrepeso (DHL)',sobrepesoTotal]);
    if(excesoTotal>0)       extras.push(['Exceso de tamaño (DHL)',excesoTotal]);
    if(noConvencionalTotal>0)extras.push(['Pieza no convencional 25–70 kg (DHL)',noConvencionalTotal]);
    if(seguroObj.monto>0)   extras.push(['Seguro DHL',seguroObj.monto]);
    const zeDHL=calcZonaEntrega('DHL',zonaEntrega,pf,pais);
    if(zeDHL)               extras.push([zeDHL.label,zeDHL.monto]);
    if(ddp)                 extras.push(['DDP',24.05]);
    // Va DESPUÉS del margen y sin fuel, como el DDP y el resto de los recargos del courier:
    // criterio de Felipe del 29/07, la ganancia se calcula solo sobre el flete de tabla.
    if(proteccionDoc)       extras.push(['Protección de documentos (DHL)',DHL_PROTECCION_DOC]);
    // Tarifa por kilo: el flete de venta es precio × peso facturable, no flete + margen.
    const conGan          =usaPorKg?parseFloat((kgVenta*pf).toFixed(2)):fleteBase*(1+profit);
    const subtotalConSurge=conGan;
    const fuelMonto       =subtotalConSurge*fuel;
    const extrasTotal     =extras.reduce((s,r)=>s+r[1],0);
    const total           =subtotalConSurge+fuelMonto+extrasTotal;
    return{
      servicio:'DHL Express Worldwide',zona,pf,
      fleteBase,feeUSA:0,surge:0,surgeAmt:0,flete:fleteBase,
      conGan,subtotalConSurge,fuelMonto,extras,extrasTotal,total,
      goGreen,sobrepesoTotal,excesoTotal,noConvencionalTotal,seguro:seguroObj.monto,
      manejoCount:0,contornoExtra:0,contornoWarn:false,manejo:0,
      minPesoAplicado:false,avisosTope:topesDHL,
      tarifa50,avisoTarifa50:tarifa50?MSG_TARIFA_50:null,
      modoVenta:usaPorKg?'por_kg':'porcentaje',
      precioKgVenta:usaPorKg?kgVenta:null,
      pfVenta:usaPorKg?pf:null,
    };
  }

  // ── UPS (Expedited o Saver) ───────────────────────────────────────────────────
  const zona=resolverZona(pais,servicio,tipo)||(zonaOverride?Number(zonaOverride):null);
  if(!zona)return null;
  // Los extras dimensionales se resuelven ANTES de buscar la tarifa, porque el Paquete de
  // Mayor Tamaño impone un mínimo de 40 kg facturables por bulto y eso cambia el flete.
  const{manejoCount,contornoExtra,contornoWarn,minPesoExtra,minPesoAplicado}=calcUPSDimExtras(bultosProc);
  const topesUPS=calcTopesPieza(bultosProc).ups;
  const pfRound=Math.ceil((pf+minPesoExtra)*2)/2;
  // IPF (International Processing Fee): 2.50 USD por envío. Es un cargo de la aduana de
  // ESTADOS UNIDOS para los envíos que llegan allá. Antes acá también se le cobraba a
  // Canadá, que no figura en el comunicado de UPS.
  const feeUSA=(tipo==='export'&&pais==='Estados Unidos')?2.50:0;
  let fleteBase;
  const servicioLabel=servicio==='UPS_EXP'?'UPS Worldwide Expedited':'UPS Worldwide Saver';
  if(servicio==='UPS_EXP'){
    const liqd=tipo==='import'?UPS_I_LIQD:UPS_E_LIQD;
    const pk  =tipo==='import'?UPS_I_PK  :UPS_E_PK;
    const mn  =tipo==='import'?UPS_I_MN  :UPS_E_MN;
    fleteBase=getUPS(liqd,pk,mn,zona,pfRound);
  } else {
    const esEsIt=tipo==='export'&&(pais==='España'||pais==='Italia');
    if(esEsIt){
      fleteBase=getUPSSaverEsIt(pais,pfRound);
    } else {
      const liqd=tipo==='import'?UPS_SI_LIQD:UPS_SE_LIQD;
      const pk  =tipo==='import'?UPS_SI_PK  :UPS_SE_PK;
      const mn  =tipo==='import'?UPS_SI_MN  :UPS_SE_MN;
      fleteBase=getUPS(liqd,pk,mn,zona,pfRound);
    }
  }
  const surge=getSurge(pais,tipo,pfRound);
  // El IPF pasa A COSTO: no lleva ganancia ni combustible. Antes se sumaba al flete
  // antes del margen, así que con 120% de utilidad esos 2.50 le llegaban al cliente
  // como 5.50, y con el fuel encima como 7.26. Criterio de Felipe (29/07): los recargos
  // del courier se pasan al costo, igual que el surge y el DDP.
  const flete=fleteBase;
  const seguroObj=calcSeguroUPS(fob,seguroPropio);
  const manejo=parseFloat((manejoCount*27.65+contornoExtra).toFixed(2));
  const extras=[];
  if(manejoCount>0)  extras.push([`Manejo adicional (${manejoCount} bulto${manejoCount>1?'s':''})`,manejoCount*27.65]);
  if(contornoExtra>0)extras.push(['Paquete mayor tamaño — contorno >300 cm',contornoExtra]);
  if(seguroObj.monto>0)extras.push(['Seguro',seguroObj.monto]);
  const zeUPS=calcZonaEntrega('UPS',zonaEntrega,pf,pais);
  if(zeUPS)          extras.push([zeUPS.label,zeUPS.monto]);
  // Entrega residencial: 6.00. Verificado contra las facturas REALES de julio 2026
  // (auditoría del 28/08): UPS facturó "Residential 6.00" en las 50 apariciones, sin
  // excepción. Acá decía 5.65 con un comentario que aseguraba que 6.00 era la tarifa
  // nacional — la factura dice lo contrario. Subido a 6.00 con el OK de Felipe (28/08).
  if(residencial)    extras.push(['Entrega residencial',6.00]);
  if(ddp)            extras.push(['DDP',24.05]);
  if(feeUSA>0)       extras.push(['Tarifa de procesamiento internacional (EE.UU.)',feeUSA]);
  // Tarifa por kilo: el flete de venta es precio × peso facturable. Se usa pfRound, que es
  // el peso que UPS efectivamente factura (redondeo a 0,5 kg y mínimo de 40 kg del Paquete
  // de Mayor Tamaño), para que el cliente pague por los mismos kilos que paga el courier.
  const conGan          =usaPorKg?parseFloat((kgVenta*pfRound).toFixed(2)):flete*(1+profit);
  const subtotalConSurge=conGan+surge;
  const fuelMonto       =subtotalConSurge*fuel;
  const extrasTotal     =extras.reduce((s,r)=>s+r[1],0);
  const total           =subtotalConSurge+fuelMonto+extrasTotal;
  return{
    servicio:servicioLabel,zona,pf:pfRound,
    fleteBase,feeUSA,surge,surgeAmt:surge,flete,
    conGan,subtotalConSurge,fuelMonto,extras,extrasTotal,total,
    manejoCount,contornoExtra,contornoWarn,manejo,
    seguro:seguroObj.monto,goGreen:0,dhlDimExtra:0,
    minPesoAplicado,minPesoExtra,avisosTope:topesUPS,
    modoVenta:usaPorKg?'por_kg':'porcentaje',
    precioKgVenta:usaPorKg?kgVenta:null,
    pfVenta:usaPorKg?pfRound:null,
  };
}

